    Returns a list of [character, count] for each maximal run of equal characters.
    Handles strings, bytes, and other iterables by converting to string.
    """
    # Convert bytes/bytearray to string using utf-8 ignore errors
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode('utf-8')
        except Exception:
            s = s.decode('utf-8', errors='ignore')
    # For non-string types, fallback to string representation
    if not isinstance(s, str):
        s = str(s)
    if not s:
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
