def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find position to insert x in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

