def solve(matrix):
    """Return the elements of the matrix in clockwise spiral order.
    Handles empty matrix and non‑rectangular input gracefully by traversing
    based on actual row lengths.
    """
    if not matrix:
        return []
    # Determine boundaries
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max(len(row) for row in matrix) - 1
    result = []
    while top <= bottom and left <= right:
        # traverse from left to right on top row
        for col in range(left, right + 1):
            if col < len(matrix[top]):
                result.append(matrix[top][col])
        top += 1
        # traverse downwards on right column
        for row in range(top, bottom + 1):
            if right < len(matrix[row]):
                result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
